#!/usr/bin/env python3
"""Deterministic read-only repository evidence collector for EDARSAHUB Worker."""
from __future__ import annotations

import argparse
import ast
import json
import re
import subprocess
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[2]
TEXT_SUFFIXES = {'.py', '.js', '.jsx', '.ts', '.tsx', '.sql', '.md', '.json', '.yml', '.yaml'}
EXCLUDED_PARTS = {'.git', 'node_modules', 'dist', 'build', '.venv', 'venv', '__pycache__', 'graphify-out'}
ROUTE_RE = re.compile(r'@(?:router|app)\.(get|post|put|patch|delete)\(\s*[\"\']([^\"\']+)[\"\']')
JS_EXPORT_RE = re.compile(r'\bexport\s+(?:default\s+)?(?:async\s+)?(?:function|class|const|let|var)\s+([A-Za-z_$][A-Za-z0-9_$]*)')
SECRET_NAME_RE = re.compile(r'(password|passwd|secret|token|api[_-]?key|authorization|connection[_-]?string)', re.I)

def run_git(args: list[str]) -> str:
    proc = subprocess.run(['git', '-C', str(ROOT), *args], text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False)
    if proc.returncode != 0:
        raise RuntimeError('GIT_READ_FAILED')
    return proc.stdout

def safe_root(value: str) -> str:
    path = Path(value)
    if path.is_absolute() or '..' in path.parts or (path.parts and path.parts[0] == '.git'):
        raise ValueError('INVALID_ROOT')
    return path.as_posix().rstrip('/')

def included(path: str, roots: list[str]) -> bool:
    parts = Path(path).parts
    if any(part in EXCLUDED_PARTS for part in parts):
        return False
    if not roots:
        return True
    return any(path == root or path.startswith(root + '/') for root in roots)

def python_symbols(path: Path) -> list[dict[str, Any]]:
    try:
        tree = ast.parse(path.read_text(encoding='utf-8', errors='ignore'))
    except Exception:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            out.append({'name': node.name, 'kind': 'class' if isinstance(node, ast.ClassDef) else 'function', 'line': getattr(node, 'lineno', None)})
    return out[:500]

def text_evidence(path: Path) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    routes: list[dict[str, Any]] = []
    symbols: list[dict[str, Any]] = []
    if path.suffix.lower() not in TEXT_SUFFIXES:
        return routes, symbols
    try:
        text = path.read_text(encoding='utf-8', errors='ignore')
    except Exception:
        return routes, symbols
    if path.suffix.lower() == '.py':
        symbols.extend(python_symbols(path))
        for match in ROUTE_RE.finditer(text):
            line = text.count('\n', 0, match.start()) + 1
            routes.append({'method': match.group(1).upper(), 'path': match.group(2), 'line': line})
    elif path.suffix.lower() in {'.js', '.jsx', '.ts', '.tsx'}:
        for match in JS_EXPORT_RE.finditer(text):
            line = text.count('\n', 0, match.start()) + 1
            symbols.append({'name': match.group(1), 'kind': 'export', 'line': line})
    return routes[:500], symbols[:500]

def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument('--roots-json', default='[]')
    parser.add_argument('--max-files', type=int, default=10000)
    args = parser.parse_args()
    roots_raw = json.loads(args.roots_json)
    if not isinstance(roots_raw, list):
        raise ValueError('ROOTS_MUST_BE_LIST')
    roots = [safe_root(str(item)) for item in roots_raw if str(item).strip()]
    if args.max_files < 1 or args.max_files > 50000:
        raise ValueError('INVALID_MAX_FILES')
    tracked = [line for line in run_git(['ls-files']).splitlines() if line.strip()]
    selected = [path for path in tracked if included(path, roots)]
    truncated = len(selected) > args.max_files
    selected = selected[:args.max_files]
    extensions = Counter()
    top_roots = Counter()
    evidence: dict[str, dict[str, Any]] = {}
    for relative in selected:
        repo_path = ROOT / relative
        suffix = repo_path.suffix.lower() or '<none>'
        extensions[suffix] += 1
        top_roots[Path(relative).parts[0] if Path(relative).parts else '<root>'] += 1
        routes, symbols = text_evidence(repo_path)
        item: dict[str, Any] = {}
        if routes:
            item['api_routes'] = routes
        if symbols:
            item['symbols'] = symbols
        if item:
            evidence[relative] = item
    payload = {
        'schema': 'edarsahub.repository-readonly-audit.v1',
        'mode': 'READ_ONLY_REPOSITORY_AUDIT',
        'repository': 'rbalam/EDARSA_HUB',
        'base_sha': run_git(['rev-parse', 'HEAD']).strip(),
        'roots': roots,
        'tracked_files_total': len(tracked),
        'selected_files_total': len(selected),
        'truncated': truncated,
        'extensions': dict(sorted(extensions.items())),
        'top_roots': dict(sorted(top_roots.items())),
        'files': selected,
        'evidence': evidence,
        'secrets_values_emitted': False,
        'production_touched': False,
    }
    print(json.dumps(payload, ensure_ascii=False, sort_keys=True))
    return 0

if __name__ == '__main__':
    raise SystemExit(main())
